  function secretTable(ctx, options = {}) {
    const { ui, data, state } = ctx;
    const search = (state.filters.secretSearch || '').toLowerCase();
    const scope = options.scope || 'all';
    const filtered = data.secrets.filter((secret)=> (!search || secret.name.toLowerCase().includes(search)) && (scope==='all' || secret.scope===scope));
    const rows = filtered.map((secret)=>`<tr class="${state.selectedSecretId===secret.id?'selected-row':''}"><td><div class="secret-name">${ui.icon('lock',14)}<div><button class="btn btn-ghost btn-sm" style="padding:0;min-height:auto;color:var(--text-1)" data-action="open-secret" data-payload='${JSON.stringify({secretId:secret.id})}'>${ui.esc(secret.name)}</button><span class="secret-mask">••••••••••••</span></div></div></td><td>${ui.badge(secret.type==='secret'?'success':'info',{label:secret.type==='secret'?'Secret':'Variable',icon:false})}</td><td>${ui.esc(secret.scope)}</td><td><button class="btn btn-ghost btn-sm" data-action="open-secret" data-payload='${JSON.stringify({secretId:secret.id})}'>${secret.used}</button></td><td>${ui.esc(secret.updated)}<div class="table-secondary">${ui.esc(secret.user)}</div></td><td>${ui.esc(secret.permission)}</td><td><div class="table-actions"><button class="icon-btn" data-action="open-secret" data-payload='${JSON.stringify({secretId:secret.id})}'>${ui.icon('eye',14)}</button><button class="icon-btn" data-action="delete-secret" data-payload='${JSON.stringify({secretId:secret.id})}'>${ui.icon('trash',14)}</button></div></td></tr>`).join('');
    return `<section class="card table-card"><div class="filters"><div class="search-box">${ui.icon('search',16)}<input class="input" data-filter="secretSearch" data-preserve="secretSearch" value="${ui.esc(state.filters.secretSearch||'')}" placeholder="搜索 Secrets…"/></div><select class="select"><option>全部作用域</option><option>Repository</option><option>Production</option><option>Staging</option></select><select class="select"><option>全部类型</option><option>Secret</option><option>Variable</option></select>${ui.button('筛选',{icon:'filter',action:'toast',payload:{message:'高级 Secret 筛选已应用'}})}</div><div class="table-scroll"><table><thead><tr><th>名称</th><th>类型</th><th>作用域</th><th>使用次数</th><th>最后更新</th><th>权限</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>${renderDataTableFooter(ui,'Secrets',filtered.length)}</section>`;
  }

