    return `${repoHeader(ctx,'settings')}<div class="grid grid-settings">${settingsNav(ctx,'repo','badge')}<div class="stack">${ui.pageHeader('状态徽章','生成可嵌入 README 或文档的流水线状态徽章。')}<div class="grid grid-sidebar"><section class="settings-section"><div class="settings-section-header"><h2>徽章配置</h2></div><div class="settings-section-body stack">${ui.field('分支',ui.select('badgeBranch',data.branches.map(b=>b.name),'main'))}${ui.field('样式',`<div class="segmented">${['flat','compact','minimal'].map(item=>`<button class="${style===item?'active':''}" data-action="set-badge-style" data-payload='${JSON.stringify({style:item})}'>${item}</button>`).join('')}</div>`)}${ui.field('格式',ui.select('format',['SVG','Markdown','HTML'],'SVG'))}${ui.field('徽章 URL',`<div class="secret-value"><code>${ui.esc(badgeUrl)}</code><button class="icon-btn" data-action="copy-text" data-payload='${JSON.stringify({text:badgeUrl})}'>${ui.icon('copy',15)}</button></div>`)}${ui.field('Markdown',`<div class="secret-value"><code>[![status](${ui.esc(badgeUrl)})](#/repos/${repo.id})</code><button class="icon-btn" data-action="copy-text" data-payload='${JSON.stringify({text:`[![status](${badgeUrl})](https://ci.acme.example/repos/${repo.id})`})}'>${ui.icon('copy',15)}</button></div>`)}</div></section><aside class="card"><div class="card-header"><h2>预览</h2></div><div class="card-body" style="min-height:220px;display:grid;place-items:center"><div style="display:flex;border-radius:${style==='minimal'?'4px':'6px'};overflow:hidden;font-weight:700;font-size:${style==='compact'?'10px':'12px'};box-shadow:var(--shadow-sm)"><span style="padding:6px 10px;background:#303b43;color:#fff">build</span><span style="padding:6px 10px;background:#1faa59;color:#fff">passing</span></div></div></aside></div></div></div>`;
