    return `${ui.pageHeader(forge.name, `${forge.type} · ${forge.url}`,`${ui.button('测试连接',{icon:'refresh',action:'test-forge',payload:{forgeId:forge.id}})}${ui.button('保存更改',{variant:'primary',icon:'check',action:'toast',payload:{message:'Forge 配置已保存'}})}`,'Forge')}<div class="grid grid-settings">${settingsNav(ctx,'admin','forges')}<form class="stack" data-form="forge-settings"><section class="settings-section"><div class="settings-section-header"><h2>连接设置</h2></div><div class="settings-section-body"><div class="form-grid">${ui.field('显示名称',ui.input('name',forge.name))}${ui.field('Forge 类型',ui.select('type',['GitHub','GitLab','Gitea','Bitbucket'],forge.type))}${ui.field('服务器 URL',ui.input('url',forge.url,{type:'url'}))}${ui.field('Client ID',ui.input('client',forge.client))}${ui.field('Client Secret',ui.input('secret','••••••••••••',{type:'password'}))}${ui.field('回调 URL',ui.input('callback','https://ci.acme.example/authorize',{disabled:true}))}</div></div></section><section class="settings-section"><div class="settings-section-header"><h2>Webhook 与同步</h2></div><div class="settings-section-body"><div class="setting-row"><div><h3>自动安装 Webhook</h3><p>仓库启用时自动创建 Hook。</p></div><label class="switch"><input type="checkbox" ${forge.webhook?'checked':''}/><span></span></label></div><div class="setting-row"><div><h3>定期同步仓库</h3><p>每 30 分钟刷新组织、权限和仓库列表。</p></div><label class="switch"><input type="checkbox" checked/><span></span></label></div></div></section></form></div>`;
